Method.Source:
void insert()
{
    //Query   		   query;
    //QueryRun                   queryRun;
    //QueryBuildDataSource        qbds;
    //QueryBuildRange         qbr,qbr2, qbr3;
    DMFEntity entity;

    next insert();



    if(this.ErrorMessage != '')
    {
        ISMTelemetryDMF telemetry = new ISMTelemetryDMF();
        telemetry.addRuntimeProperty("defGroupName", this.DefinitionGroupName);
        telemetry.addRuntimeProperty('executionId', this.ExecutionId);
        telemetry.addRuntimeProperty('dmfEntity', this.EntityName);
        telemetry.addRuntimeProperty('stagingRecId', int642Str(this.StagingRecId));
        telemetry.addRuntimeProperty('stagingColumnName', this.StagingColumnName);
        telemetry.addRuntimeProperty('errorMessage', this.ErrorMessage);
        telemetry.addRuntimeProperty('sourceOrTarget', enum2Str(this.SourceTarget));

        //get the staging record.
        entity = DMFEntity::find(this.EntityName);
        //SysDictTable dictTable = new   SysDictTable(tableName2Id(entity.EntityTable));

        DictTable dictTable = new DictTable(tableName2Id(entity.EntityTable));
        Common c2 = dictTable.makeRecord();

        select c2
            where c2.RecId == this.StagingRecId;


        telemetry.addRuntimeProperty('stagingRecord', JsonSerializer::jsonSerialize(c2), true);
        telemetry.processEvent(ISMTelemetryEventNames::DMFStagingLogMessage);
    }
}
